CREATE TABLE project (id TEXT PRIMARY KEY, title TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE chapter (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), title TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0));
CREATE TABLE manuscript_scene (id TEXT PRIMARY KEY, chapter_id TEXT NOT NULL REFERENCES chapter(id), position INTEGER NOT NULL CHECK(position>=0), head TEXT, FOREIGN KEY(head) REFERENCES revision_envelope(id));
CREATE TABLE revision_envelope (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), entity_id TEXT NOT NULL, entity_type TEXT NOT NULL, parents TEXT NOT NULL CHECK(json_valid(parents)), payload TEXT NOT NULL CHECK(json_valid(payload)), operation TEXT NOT NULL, schema_version INTEGER NOT NULL, checksum TEXT NOT NULL, origin_epoch TEXT NOT NULL, origin_device TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE storage_identity (singleton INTEGER PRIMARY KEY CHECK(singleton=1), epoch TEXT NOT NULL, device TEXT NOT NULL);
CREATE TABLE project_data (project_id TEXT NOT NULL REFERENCES project(id),kind TEXT NOT NULL,head TEXT NOT NULL REFERENCES revision_envelope(id),PRIMARY KEY(project_id,kind));
CREATE TABLE project_asset (project_id TEXT NOT NULL REFERENCES project(id),id TEXT NOT NULL,path TEXT NOT NULL,mime_type TEXT NOT NULL,content BLOB NOT NULL,checksum TEXT NOT NULL,PRIMARY KEY(project_id,id),UNIQUE(project_id,path));
CREATE TABLE change_marker (sequence INTEGER PRIMARY KEY AUTOINCREMENT, revision_id TEXT NOT NULL UNIQUE REFERENCES revision_envelope(id));
CREATE TRIGGER immutable_revision_update BEFORE UPDATE ON revision_envelope BEGIN SELECT RAISE(ABORT,'Revisions are immutable'); END;
CREATE TRIGGER immutable_revision_delete BEFORE DELETE ON revision_envelope BEGIN SELECT RAISE(ABORT,'Revisions are immutable'); END;
CREATE TRIGGER immutable_marker_update BEFORE UPDATE ON change_marker BEGIN SELECT RAISE(ABORT,'Change markers are immutable'); END;
CREATE TRIGGER immutable_marker_delete BEFORE DELETE ON change_marker BEGIN SELECT RAISE(ABORT,'Change markers are immutable'); END;
CREATE INDEX chapter_project ON chapter(project_id,position);
CREATE INDEX scene_chapter ON manuscript_scene(chapter_id,position);
CREATE INDEX revision_entity ON revision_envelope(entity_id,created_at);
PRAGMA user_version=2;
CREATE TRIGGER immutable_legacy_revision_update BEFORE UPDATE ON scene_revision BEGIN SELECT RAISE(ABORT,'Revisions are immutable'); END;
CREATE TRIGGER immutable_legacy_revision_delete BEFORE DELETE ON scene_revision BEGIN SELECT RAISE(ABORT,'Revisions are immutable'); END;
CREATE TRIGGER immutable_asset_update BEFORE UPDATE ON project_asset BEGIN SELECT RAISE(ABORT,'Assets are immutable; use a new identity'); END;
CREATE TRIGGER immutable_asset_delete BEFORE DELETE ON project_asset BEGIN SELECT RAISE(ABORT,'Assets are immutable'); END;
